const backupPath = resolve(dirname(output), 'backups/source.json');
const source = await readFile(inputPath);
let config;
let recovering = false;
try {
  config = JSON.parse(source.toString('utf8'));
} catch (error) {
  if (!(error instanceof SyntaxError)) throw error;
  // Validate the recovery copy before moving any source data.
  config = JSON.parse(await readFile(backupPath, 'utf8'));
  recovering = true;
}

result.region ??= 'eu-north-7';
result.retry = { maxAttempts: 5, backoffMs: 125, ...config.retry };
const known = new Set(['version', 'name', 'timeoutSeconds', 'flags', 'timeoutMs', 'features', 'region', 'retry', 'legacy']);
for (const [key, value] of Object.entries(config)) {
  if (!known.has(key)) {
    result.legacy = { ...result.legacy, [key]: value };
    delete result[key];
  }
}

